===== InvoiceRepository =====
package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.util.List;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

/**
 * Data access for {@link Invoice}. A Spring Data bean, injected into the OfficeFloor logic classes
 * that back the /api/invoices routes.
 */
public interface InvoiceRepository extends JpaRepository<Invoice, Long> {

    /** All invoices, oldest first, so the list order is stable for the UI and tests. */
    List<Invoice> findAllByOrderByIdAsc();

    /**
     * Every invoice at one lifecycle stage, oldest first, backing the all-invoices status filter.
     * The stable oldest-first order matches {@link #findAllByOrderByIdAsc()} so filtering only
     * narrows the list, never reorders it.
     */
    List<Invoice> findByStatusOrderByIdAsc(String status);

    /**
     * One page of invoices at one lifecycle stage, ordered by the supplied {@link Pageable} (the
     * all-invoices list orders by id ascending). Backs the all-invoices list's next/previous paging
     * when a status filter is active — only the requested slice is fetched, so a huge list is shown a
     * page at a time rather than all at once.
     */
    Page<Invoice> findByStatus(String status, Pageable pageable);

    /**
     * All invoices, earliest due date first (id as a stable tiebreaker), backing the project
     * invoices' sort-by-due-date control.
     */
    List<Invoice> findAllByOrderByDueDateAscIdAsc();

    /**
     * The money still owed: the sum of every SENT invoice's amount, or 0 when none are sent. Only
     * invoices that have actually been sent count — a DRAFT has not gone out yet, and a PAID one has
     * already been settled — so both are excluded. Backs the dashboard's outstanding total
     * ({@code GET /api/dashboard}).
     */
    @Query("SELECT COALESCE(SUM(i.amount), 0) FROM Invoice i WHERE i.status = 'SENT'")
    BigDecimal sumSentAmount();

    /**
     * How many SENT invoices are overdue as of {@code asOf}: an invoice whose due date has already
     * passed and which has actually gone out. Only SENT counts — a DRAFT has not been sent and a PAID
     * one is settled — and "overdue" means the due date is strictly before the reference day. Due
     * dates are ISO date literals (YYYY-MM-DD), which sort lexically = chronologically, so a string
     * comparison is the date comparison. Backs the dashboard's overdue count ({@code
     * GET /api/dashboard}).
     */
    @Query("SELECT COUNT(i) FROM Invoice i WHERE i.status = 'SENT' "
            + "AND i.dueDate IS NOT NULL AND i.dueDate < :asOf")
    long countSentOverdue(@Param("asOf") String asOf);

    /**
     * The total invoiced against one project: the sum of every invoice's amount raised against it, or
     * 0 when it has none. Backs the project budget panel's "invoiced" figure ({@code
     * GET /api/projects/budget}).
     */
    @Query("SELECT COALESCE(SUM(i.amount), 0) FROM Invoice i WHERE i.projectId = :projectId")
    BigDecimal sumAmountByProjectId(@Param("projectId") Long projectId);
}
===== Invoice =====
package net.officefloor.hq.app;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import jakarta.persistence.Transient;
import java.math.BigDecimal;

/**
 * An invoice raised against a project: the id of the {@link Project} it belongs to and a money
 * amount. Mapped to the {@code invoice} table created by {@code V4__invoices.sql}. IDENTITY id so
 * the DB assigns it on insert (seed inserts explicit ids via JdbcTemplate; GENERATED BY DEFAULT
 * allows both).
 */
@Entity
@Table(name = "invoice")
public class Invoice {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "project_id")
    private Long projectId;

    private BigDecimal amount;

    /**
     * Lifecycle status: DRAFT by default, SENT once sent, PAID once paid (see V5__invoice_status.sql
     * and V11__invoice_draft_default.sql).
     */
    private String status;

    /** The day the invoice went out, an ISO date literal (see V9__invoice_dates.sql). */
    @Column(name = "issued_date")
    private String issuedDate;

    /** The day the invoice is due, an ISO date literal (see V9__invoice_dates.sql). */
    @Column(name = "due_date")
    private String dueDate;

    /**
     * How much is still owed on this invoice: its {@link #amount} minus every payment recorded
     * against it. Derived, not stored — {@code @Transient} keeps it out of the {@code invoice}
     * table; {@link InvoicesGet} fills it from the payments before sending the list so the project
     * invoices view can show the amount still due after payments.
     */
    @Transient
    private BigDecimal amountDue;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public Long getProjectId() {
        return projectId;
    }

    public void setProjectId(Long projectId) {
        this.projectId = projectId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public String getStatus() {
        return status;
    }

    public void setStatus(String status) {
        this.status = status;
    }

    public String getIssuedDate() {
        return issuedDate;
    }

    public void setIssuedDate(String issuedDate) {
        this.issuedDate = issuedDate;
    }

    public String getDueDate() {
        return dueDate;
    }

    public void setDueDate(String dueDate) {
        this.dueDate = dueDate;
    }

    public BigDecimal getAmountDue() {
        return amountDue;
    }

    public void setAmountDue(BigDecimal amountDue) {
        this.amountDue = amountDue;
    }
}
===== InvoiceView =====
package net.officefloor.hq.app;

import java.math.BigDecimal;

/**
 * What the {@code /api/invoices/all} route returns: an invoice plus the NAME of the project it is
 * for, so the one-place invoices list shows the project's name (not its id) and its lifecycle
 * status without a second lookup. Built by joining {@link Invoice} against {@link Project} in
 * {@link InvoicesAllGet}, mirroring how {@link ProjectView} carries the client's name.
 */
public class InvoiceView {

    private final Long id;
    private final Long projectId;
    private final String projectName;
    private final BigDecimal amount;
    private final String status;
    private final String issuedDate;
    private final String dueDate;

    public InvoiceView(Long id, Long projectId, String projectName, BigDecimal amount,
            String status, String issuedDate, String dueDate) {
        this.id = id;
        this.projectId = projectId;
        this.projectName = projectName;
